-- =====================================================================
-- Reference data import — generated by scripts/db/import-references.mjs
-- Source: snapshot/baseline.json
--   10 documents, each with one baseline revision, published
--   322 document → metric references (document_metric_refs)
--   21 linked phrases
--
-- Apply ONCE, by hand, as the database owner, after every migration and after
-- supabase/imports/metrics_baseline.sql. This is not a migration and must not
-- be applied automatically.
--
-- Reads public.metrics only to resolve metric keys. It never inserts, updates
-- or deletes a metric, so no version row, verification state or archive state
-- changes. It refuses to run unless the four reference tables are empty and
-- the 134 baseline metrics are present and active, and it checks
-- every count before committing; any failure rolls the whole import back.
--
-- Linked phrases are imported unreviewed (reviewed_at null): no review is
-- recorded that did not happen.
--
-- A field that names the same metric in more than one format stores format null:
--   case_study/preschool-google-ads intro.0 pre.accounts: words_capitalised, words → null
-- =====================================================================

begin;

-- 1. Preconditions ------------------------------------------------------

do $$
declare
  v_missing text[];
begin
  if exists (select 1 from public.documents) then
    raise exception 'public.documents is not empty; the reference import runs once, on empty tables';
  end if;
  if exists (select 1 from public.document_revisions) then
    raise exception 'public.document_revisions is not empty; the reference import runs once, on empty tables';
  end if;
  if exists (select 1 from public.document_metric_refs) then
    raise exception 'public.document_metric_refs is not empty; the reference import runs once, on empty tables';
  end if;
  if exists (select 1 from public.linked_phrases) then
    raise exception 'public.linked_phrases is not empty; the reference import runs once, on empty tables';
  end if;
  if (select count(*) from public.metrics) <> 134 then
    raise exception 'expected exactly 134 metrics, found %; import the metric baseline first', (select count(*) from public.metrics);
  end if;
  if exists (select 1 from public.metrics where archived_at is not null) then
    raise exception 'archived metrics found; the snapshot references only active metrics';
  end if;

  select array_agg(k order by k) into v_missing
  from unnest(array['audit.acct_inflated.campaign_1.conv_rate', 'audit.acct_inflated.campaign_2.conv_rate', 'audit.acct_inflated.campaign_3.conv_rate', 'audit.acct_inflated.campaign_4.conv_rate', 'audit.acct_inflated.conv_rate', 'audit.acct_inflated.spend', 'audit.incomplete_tracking.sources', 'audit.incomplete_tracking.spend', 'audit.placeholder_conversion_value', 'audit.placeholder_value_campaigns', 'audit.unreliable_share', 'audit.unreliable_spend', 'cc.campaigns', 'cc.google.campaigns', 'cc.google.clicks', 'cc.google.cpc', 'cc.google.ctr', 'cc.google.impressions', 'cc.google.reported_conversion_rate_1', 'cc.google.reported_conversion_rate_2', 'cc.google.reported_conversion_rate_3', 'cc.google.spend', 'cc.google_1.clicks', 'cc.google_1.spend', 'cc.google_2.clicks', 'cc.google_2.spend', 'cc.google_3.clicks', 'cc.google_3.spend', 'cc.meta.campaigns', 'cc.meta.cpl_max', 'cc.meta.cpl_min', 'cc.meta.leads', 'cc.meta.spend', 'cc.meta_1.cpl', 'cc.meta_1.leads', 'cc.meta_1.spend', 'cc.meta_2.cpl', 'cc.meta_2.leads', 'cc.meta_2.spend', 'cc.total.spend', 'pre.account_a.conversion_actions.actively_recording', 'pre.account_a.conversion_actions.no_recent_conversions', 'pre.account_a.conversion_actions.unverified', 'pre.account_a.pmax.clicks', 'pre.account_a.pmax.cpc', 'pre.account_a.pmax.recorded_conversions', 'pre.account_a.pmax.reported_funnel_leads', 'pre.account_a.pmax.spend', 'pre.account_a.recorded_conversions', 'pre.account_a.search.clicks', 'pre.account_a.search.cpc', 'pre.account_a.search.recorded_conversions', 'pre.account_a.search.spend', 'pre.account_a.spend', 'pre.account_b.recorded_conversions', 'pre.account_b.search.clicks', 'pre.account_b.search.recorded_conversions', 'pre.account_b.search.spend', 'pre.account_b.smart.clicks', 'pre.account_b.smart.recorded_conversions', 'pre.account_b.smart.spend', 'pre.account_b.spend', 'pre.account_c.pmax.clicks', 'pre.account_c.pmax.recorded_conversions', 'pre.account_c.pmax.spend', 'pre.account_c.recorded_conversions', 'pre.account_c.search_2.clicks', 'pre.account_c.search_2.recorded_conversions', 'pre.account_c.search_2.spend', 'pre.account_c.smart.clicks', 'pre.account_c.smart.recorded_conversions', 'pre.account_c.smart.spend', 'pre.account_c.spend', 'pre.accounts', 'pre.total.recorded_conversions', 'pre.total.spend', 're.blended_cpl', 're.cohort.cpl_change_pct', 're.cohort.lead_multiple', 're.cohort.spend_multiple', 're.cohort_2025.cpl', 're.cohort_2025.leads', 're.cohort_2025.spend', 're.cohort_2026.cpl', 're.cohort_2026.leads', 're.cohort_2026.spend', 're.form_submissions', 're.project_a.cpl', 're.project_a.leads', 're.project_b.cpl', 're.project_b.leads', 're.project_c.cpl', 're.project_c.leads', 're.project_d.cpl', 're.project_d.leads', 're.project_e.cpl', 're.project_e.leads', 're.result_type.messaging.cost_per_result', 're.result_type.native_call.cost_per_result', 're.result_type.quality_lead.cost_per_result', 're.result_type.standard_lead.cost_per_result', 're.structure.ad_sets', 're.structure.ads', 're.structure.campaigns', 're.structure.cities', 're.structure.objectives', 're.top5.campaign_count', 're.top5.cpl', 're.top5.cpl_spread', 're.top5.leads', 're.top5.spend', 're.variant.campaign_count', 're.variant.project_c.original.cpl', 're.variant.project_c.original.leads', 're.variant.project_c.original.spend', 're.variant.project_c.variant.cpl', 're.variant.project_c.variant.leads', 're.variant.project_c.variant.spend', 're.variant.project_f.original.cpl', 're.variant.project_f.original.leads', 're.variant.project_f.original.spend', 're.variant.project_f.variant.cpl', 're.variant.project_f.variant.leads', 're.variant.project_f.variant.spend', 're.variant.project_g.original.cpl', 're.variant.project_g.original.leads', 're.variant.project_g.original.spend', 're.variant.project_g.variant.cpl', 're.variant.project_g.variant.leads', 're.variant.project_g.variant.spend', 're.zero_result_lead_spend', 'site.accounts', 'site.evidence_months', 'site.spend_total']::text[]) as k
  where not exists (select 1 from public.metrics m where m.metric_key = k);
  if v_missing is not null then
    raise exception 'referenced metrics do not exist: %', v_missing;
  end if;

  -- Recorded for the final check that no metric was touched.
  perform set_config('reference_import.metric_versions', (select count(*) from public.metric_versions)::text, true);
  perform set_config('reference_import.metrics_updated', coalesce((select max(updated_at) from public.metrics)::text, ''), true);
end
$$;

