insert into public.documents (doc_type, slug, status, schema_version, draft, sort_order)
values
  ('proof_strip', 'proof-strip', 'draft', 1, $ref${"proofMetrics":[{"value":"{{metric:site.spend_total||+}}","label":"documented ad spend","evidence":"{{evidence:site.spend_total}}"},{"value":"{{metric:re.form_submissions}}","label":"Meta form submissions","evidence":"{{evidence:re.form_submissions}}"},{"value":"{{metric:site.accounts}}","label":"ad accounts documented","evidence":"{{evidence:site.accounts}}"},{"value":"{{metric:site.evidence_months}}","label":"campaign evidence","evidence":"{{evidence:site.evidence_months}}"}],"proofMethodologyNote":"Based on documented campaign exports and analysis. Metrics have defined limitations and are presented conservatively."}$ref$::jsonb, 0),
  ('homepage', 'home', 'draft', 1, $ref${"hero":{"eyebrow":"Performance Marketing · Meta Ads · Google Ads","h1":"Performance Marketing That Turns Ad Spend Into Measurable Growth","subheadline":"I help real estate and local businesses generate and improve leads through Meta Ads, Google Ads, conversion-focused landing pages, and better measurement.","primaryCta":"Get a Free Ad Audit","secondaryCta":"View Case Studies","trustLine":"Real campaign evidence. Clear measurement. No inflated claims."},"intro":{"eyebrow":"The approach","heading":"I don’t just run ads. I diagnose what the data is actually telling you.","body":["Good performance marketing is not just about launching campaigns.","It is about understanding the whole path — and knowing which part of it is actually costing you."],"chain":["Ad","Landing Page","Lead","Qualification","Business Outcome"],"closing":"I combine campaign execution with analysis and measurement so that optimisation decisions are based on evidence rather than assumptions."},"servicesSection":{"eyebrow":"Services","heading":"Four areas, one job: making spend accountable","subheading":"Acquisition, the page it lands on, and the measurement that tells you whether either worked.","cta":"Explore Services"},"caseStudiesSection":{"eyebrow":"Evidence","heading":"Selected Campaign Evidence","subheading":"Real campaign data, decisions and limitations — not polished numbers without context.","cta":"View all case studies"},"howIWork":{"eyebrow":"How I work","heading":"Measurement first, then scale","subheading":"A sequence, not a menu. Each step exists because skipping it makes the next one unreliable."},"whyWorkWithMe":{"eyebrow":"Why work with me","heading":"What you can expect from the work","subheading":"Four commitments that hold whether the numbers flatter me or not.","points":[{"title":"Evidence before assumptions","body":"Every figure I show you is labelled with how it is known — documented, calculated, platform-reported or unverified. You should never have to guess which is which.","icon":{"$icon":"ShieldCheck"}},{"title":"Measurement before optimisation","body":"I check whether the conversion data deserves to be optimised before touching budgets. In my own accounts that check found roughly a third of documented spend reporting numbers I could not stand behind.","icon":{"$icon":"Eye"}},{"title":"Analysis, not just execution","body":"Campaign work is the starting point. The value is in reading what the account is telling you — which campaigns differ, why the spread exists, and what is worth testing next.","icon":{"$icon":"LineChart"}},{"title":"The whole funnel, not just the click","body":"Ad, landing page, lead, qualification, business outcome. I work across the full path rather than optimising one step and hoping the rest holds up.","icon":{"$icon":"Workflow"}}]},"aboutSnippet":{"eyebrow":"About","heading":"I care about what happens after the click.","body":["I’m Bipin Kumar, a performance marketer based in Patna, working across Meta Ads, Google Ads, lead generation, landing pages and measurement — with a strong focus on real estate and local-business marketing.","A self-audit of my own ad accounts is what shaped how I work now: before scaling a campaign, make sure the numbers deserve your trust."],"cta":"More about how I work"},"finalCta":{"eyebrow":"Next step","heading":"Have a campaign that needs a second look?","body":"Send me your campaign setup and reporting. I will review the structure, the measurement and the obvious opportunity areas, and tell you plainly what the data supports.","note":"An initial assessment based on the information you provide — not a guarantee of performance."}}$ref$::jsonb, 0),
  ('about', 'about', 'draft', 1, $ref${"aboutContent":{"eyebrow":"About","h1":"I’m Bipin Kumar — a performance marketer focused on measurable growth.","intro":"I work across Meta Ads, Google Ads, lead generation, landing pages and measurement, with a strong focus on real estate and local-business marketing.","secondaryIntro":"Based in Patna, working with clients who need paid acquisition to produce something the business can actually act on."},"approach":{"eyebrow":"Approach","heading":"I care about what happens after the click.","body":["Ad platforms are very good at the first two steps of the path below, and structurally blind to the last two. That gap is where most wasted spend hides.","So the work I do runs the length of the chain rather than stopping where the platform’s reporting does."]},"experience":{"eyebrow":"Experience","heading":"Hands-on paid acquisition, across two very different verticals","body":["Hands-on paid acquisition experience across real estate and education campaigns, with practical exposure to campaign analysis, lead generation, creative testing, CPL analysis and measurement diagnosis.","The real estate work is lead-generation at volume: multiple residential projects, Meta lead campaigns and Google Search running in the same market, with cost per lead varying widely between projects. The education work is the opposite problem — smaller budgets, and accounts where the central question was whether the reporting could be trusted at all.","Both are documented in the case studies, including the parts that do not flatter the numbers."]},"realEstateFocus":{"eyebrow":"Primary focus","heading":"Real estate lead generation","body":"Residential property is where most of my documented campaign work sits — long consideration cycles, high lead volume, and a wide gap between a form submission and a site visit.","items":["Residential project lead generation","Meta lead campaigns","Google Search","Campaign and audience analysis","Creative testing","CPL analysis","Funnel thinking","Measurement"]},"beyondRealEstate":{"heading":"Beyond real estate","body":"Preschool and education campaigns, where the work centred on measurement diagnosis — establishing which reported numbers could support a decision before any budget was moved."},"capabilities":[{"title":"Paid Acquisition","body":"Meta Ads and Google Ads across lead generation, search and Performance Max — campaign structure, audiences, creative testing and budget allocation.","icon":{"$icon":"Target"}},{"title":"Campaign Analysis","body":"Reading an account for what it is actually saying: cohort comparison, cost-per-result spread, campaign-level variance and the questions that spread raises.","icon":{"$icon":"LineChart"}},{"title":"Conversion-Focused Web Experiences","body":"Campaign landing pages and marketing websites built around campaign intent, mobile experience, form UX and message match.","icon":{"$icon":"LayoutTemplate"}},{"title":"Tracking & Measurement","body":"Conversion definitions, tracking review across Meta and Google, UTM structure, CRM funnel thinking and cross-channel outcome comparability.","icon":{"$icon":"Gauge"}},{"title":"AI-Assisted Marketing","body":"I use AI-assisted workflows for research, analysis, content development and faster execution — while keeping final decisions grounded in campaign evidence and human judgement.","icon":{"$icon":"BrainCircuit"}}],"principles":{"eyebrow":"Principles","heading":"Three things I do not negotiate on","items":[{"number":"01","title":"Evidence before assumptions.","body":"If the data does not establish something, I say so rather than filling the gap with a confident-sounding estimate."},{"number":"02","title":"Measurement before optimisation.","body":"Optimising against numbers nobody has checked moves budget towards whichever campaign is miscounting most."},{"number":"03","title":"Business outcomes matter.","body":"A cheaper lead is only progress if it is still a lead the business wants. Platform metrics are a means, not the goal."}]},"measurementLesson":{"eyebrow":"The lesson","heading":"One lesson changed how I look at performance data.","body":["I ran a measurement audit across my own ad accounts before treating any of their numbers as a basis for optimisation.","It identified {{metric:audit.unreliable_spend}} of documented spend associated with unreliable, unverified or inflated measurement — roughly {{metric:audit.unreliable_share}} of the total. Inflated conversion rates that could not be reconciled with click volume. Placeholder {{metric:audit.placeholder_conversion_value}} conversion values. Conversion actions sitting unverified while campaigns kept spending.","None of it was visible from the top-level dashboard. All of it would have quietly corrupted every optimisation decision made against it."],"pullQuote":"Before scaling a campaign, make sure the numbers deserve your trust.","ctaLabel":"Read the full measurement audit","ctaHref":"/case-studies/measurement-audit"},"currentFocus":{"eyebrow":"Current focus","heading":"What I am building towards","items":[{"title":"Deeper performance marketing","body":"More sophisticated account structures, better creative testing discipline, and analysis that goes past the platform average."},{"title":"Conversion-focused web experiences","body":"Treating the landing page as part of the campaign rather than as a separate deliverable handed off to someone else."},{"title":"Better measurement systems","body":"Closing the loop between platform events, CRM records and business outcomes so cross-channel decisions rest on comparable numbers."}]},"recruiterSection":{"heading":"Hiring for a Performance Marketing role?","body":"The case studies on this site are the clearest picture of how I think about campaigns, analysis and measurement. The resume covers the rest."}}$ref$::jsonb, 0),
  ('services', 'services', 'draft', 1, $ref${"services":[{"slug":"meta-ads","title":"Meta Ads & Lead Generation","summary":"Campaign setup, audience strategy, lead generation, creative testing, lead forms, optimisation, CPL analysis and lead-quality measurement.","description":"End-to-end Meta lead generation: building the campaign structure, deciding what a lead should actually be, testing creative properly, and analysing cost per lead against something more useful than the platform average.","includes":["Campaign setup","Campaign structure","Audience strategy","Creative testing","Lead forms","Optimisation","CPL analysis","Lead quality measurement","Retargeting"],"bestFor":["Real estate","Local businesses","Education","Lead-generation businesses"],"evidence":{"slug":"meta-lead-generation","label":"Scaling Meta lead generation in Patna"},"icon":{"$icon":"BarChart3"}},{"slug":"google-ads","title":"Google Ads & Search Acquisition","summary":"Search campaigns, campaign structure, keyword analysis, bid strategy, conversion tracking review, search-term analysis and performance diagnosis.","description":"Search and Performance Max work that starts one step earlier than most: with the conversion data itself. Structure, keywords and bidding all follow from knowing which numbers in the account can be trusted.","includes":["Search campaigns","Performance Max review","Keyword analysis","Campaign structure","Bid strategy","Conversion tracking review","Search-term analysis","Budget allocation","Performance diagnosis"],"principle":"Before optimising Google Ads, check whether the conversion data deserves to be optimised.","evidence":{"slug":"preschool-google-ads","label":"Diagnosing preschool Google Ads across {{metric:pre.accounts|words}} accounts"},"icon":{"$icon":"Search"}},{"slug":"landing-pages","title":"Landing Pages & Marketing Websites","summary":"Conversion-focused landing pages and marketing websites designed around campaign intent, mobile experience, clear CTAs, forms and basic measurement.","description":"The step between a paid click and an enquiry — and the one most often treated as somebody else’s job. Campaign landing pages and marketing websites, built as part of the acquisition work rather than handed off separately.","includes":["Campaign landing pages","Marketing websites","Mobile-first layouts","CTA optimisation","Form UX","Campaign-message alignment","Basic tracking"],"principle":"I build landing pages that match the ad, work well on mobile, and make it easy for people to take the next step — with clear CTAs, simple forms and tracking.","icon":{"$icon":"LayoutTemplate"}},{"slug":"tracking-measurement","title":"Tracking & Measurement","summary":"Conversion definitions, Meta and Google tracking review, UTM structure, CRM funnel thinking, offline conversion strategy and cross-channel measurement.","description":"The layer most accounts skip. Deciding what a conversion means, checking whether the platforms are recording it, and making the same outcome comparable across channels so budget decisions rest on something solid.","includes":["Conversion tracking review","Conversion definitions","Meta and Google measurement","UTM structure","CRM funnel thinking","Offline conversion strategy","Cross-channel measurement"],"evidence":{"slug":"measurement-audit","label":"Auditing {{metric:site.accounts|words}} ad accounts before optimising them"},"icon":{"$icon":"Gauge"}}],"servicesPageContent":{"eyebrow":"Services","h1":"Performance Marketing Built Around Better Decisions","intro":"I work across paid acquisition, landing pages and measurement — with a focus on understanding what the data actually supports before making optimisation decisions.","secondaryIntro":"Most accounts do not need more activity. They need a clearer view of which numbers are load-bearing, and a plan that follows from it."},"funnelNodes":[{"label":"Ad","note":"Reach and intent"},{"label":"Landing Page","note":"Message match and form UX"},{"label":"Lead","note":"A recorded, defined event"},{"label":"Qualification","note":"Is this lead real and relevant?"},{"label":"Business Outcome","note":"Site visit, booking, admission, sale"}],"funnelContent":{"eyebrow":"The full path","heading":"The ad is only the beginning.","body":"Ad platforms can optimise the first two steps well. Everything after that depends on decisions made outside the platform — what counts as a lead, how it is qualified, and whether the outcome ever gets reported back. That is where most performance problems actually live."},"processSteps":[{"number":"01","title":"Understand","description":"The business, the offer, what a good lead looks like, and what a genuine outcome is worth. Before any account access."},{"number":"02","title":"Audit","description":"Campaign structure, spend allocation, conversion definitions and tracking status — establishing which numbers can carry a decision."},{"number":"03","title":"Build","description":"Campaigns, audiences, creative and landing pages, structured so that performance differences are readable rather than blended away."},{"number":"04","title":"Optimise","description":"Budget, bids, audiences and creative — against the metrics the audit established as trustworthy, not against whatever the dashboard shows first."},{"number":"05","title":"Measure","description":"Closing the loop: connecting platform events to CRM and business outcomes so the next round of decisions is better informed than the last."}],"servicesCta":{"heading":"Not sure which part of your funnel needs fixing?","body":"Send me what you have — account access, exports or even screenshots — and I will tell you what the data supports and where it stops."}}$ref$::jsonb, 0),
  ('contact', 'contact', 'draft', 1, $ref${"contactContent":{"eyebrow":"Contact","h1":"Have a campaign that needs a second look?","intro":"Send me what you have — campaign exports, account access, or even screenshots of your reporting. I will tell you what the data supports, where it stops, and what I would look at first.","primaryCta":"Get a Free Ad Audit","secondaryCta":"Chat on WhatsApp","responseNote":"I read every enquiry personally and reply to the ones I can genuinely help with."},"auditOffer":{"heading":"Get a Free Ad Audit","body":"I’ll review your campaign setup, measurement and obvious opportunity areas based on the information you provide.","disclaimer":"This is an initial assessment, not a guarantee of performance.","covers":[{"title":"Campaign structure","body":"How campaigns, ad sets and budgets are organised, and whether that structure lets you read performance or hides it."},{"title":"Measurement integrity","body":"Whether your conversion data is being recorded, whether it is plausible, and whether it means what the dashboard implies."},{"title":"Opportunity areas","body":"The two or three things I would examine first, and what evidence would be needed to act on them."}],"boundaries":{"heading":"What it is not","items":["A performance guarantee, or a forecast of leads or revenue.","A full technical tracking implementation — that is separate, hands-on work.","A generic checklist. If your reporting looks sound, I will say so."]}},"thankYouContent":{"confirmed":{"eyebrow":"Request received","h1":"Thanks — your audit request is in.","body":"I read every enquiry myself. You will get a reply from me, not an autoresponder sequence."},"direct":{"eyebrow":"Contact","h1":"Nothing to confirm here yet.","body":"This page confirms a submitted audit request, and no submission is attached to this visit. If you meant to send one, the form takes about a minute."},"nextSteps":{"heading":"What happens next","steps":[{"number":"01","title":"I read what you sent","body":"Your campaign context, the problem you described, and anything you linked to."},{"number":"02","title":"I look at the measurement first","body":"Whether the numbers in your account can carry a decision, before looking at what the numbers say."},{"number":"03","title":"You get a straight answer","body":"What the data supports, where it stops, and the two or three things I would examine first. If your setup already looks sound, I will tell you that instead."}]},"meanwhile":{"heading":"While you wait","body":"The case studies are the clearest picture of how I work — including the parts where the evidence runs out."},"whatsappPrompt":"Want to add context or send a screenshot? WhatsApp is the fastest route.","whatsappMessage":"Hi Bipin, I just submitted an ad audit request through your website and wanted to add some context."},"recruiterCta":{"heading":"Hiring for a Performance Marketing role?","body":"The case studies show how I approach campaigns and measurement. The resume covers the rest."}}$ref$::jsonb, 0),
  ('case_study_index', 'case-studies', 'draft', 1, $ref${"caseStudyRelated":{"meta-lead-generation":{"services":[{"href":"/services/#meta-ads","label":"Meta Ads & Lead Generation"}],"caseStudy":{"slug":"cross-channel-real-estate","label":"Cross-Channel Meta + Google Ads","reason":"The same real estate market, measured across two platforms."}},"measurement-audit":{"services":[{"href":"/services/#tracking-measurement","label":"Tracking & Measurement"}],"caseStudy":{"slug":"meta-lead-generation","label":"Scaling Meta Lead Generation in Patna","reason":"The Meta lead campaigns whose spend this audit examined."}},"preschool-google-ads":{"services":[{"href":"/services/#google-ads","label":"Google Ads & Search Acquisition"}],"caseStudy":{"slug":"measurement-audit","label":"Auditing My Own Ad Accounts","reason":"The wider audit these {{metric:pre.accounts|words}} preschool accounts sit inside."}},"cross-channel-real-estate":{"services":[{"href":"/services/#meta-ads","label":"Meta Ads & Lead Generation"},{"href":"/services/#google-ads","label":"Google Ads & Search Acquisition"}],"caseStudy":{"slug":"measurement-audit","label":"Auditing My Own Ad Accounts","reason":"Where the unreliable Google conversion reporting is documented."}}},"caseStudyIndexContent":{"eyebrow":"Case Studies","heading":"Selected Campaign Evidence","subheading":"Real campaign data, decisions and limitations — not polished numbers without context.","intro":["Each case study below is built from documented campaign exports. Where the evidence supports a conclusion, it is stated plainly. Where it does not, that is stated just as plainly.","You will find cost per lead, spend, clicks and campaign structure. You will not find revenue figures, qualified-lead counts or return on ad spend, because the available evidence does not establish them."]}}$ref$::jsonb, 0),
  ('case_study', 'meta-lead-generation', 'draft', 1, $ref${"summary":{"slug":"meta-lead-generation","title":"From ₹106.66 to ₹32.29 CPL: Scaling Meta Lead Generation in Patna","cardTitle":"Scaling Meta Lead Generation in Patna","subtitle":"{{metric:re.cohort_2025.leads}} → {{metric:re.cohort_2026.leads}} leads across observed campaign cohorts, while reported CPL fell {{metric:re.cohort.cpl_change_pct}}.","cardDescription":"Residential real estate lead generation on Meta across two campaign cohorts — what the exports show about spend, lead volume and cost per lead, and what they do not.","metaDescription":"Meta Ads lead generation case study for residential real estate in Patna: cohort CPL comparison, campaign-level evidence, result-type breakdown and stated measurement limitations.","industry":"Real Estate","platform":"Meta Ads","order":1,"cardMetrics":[{"$pair":{"first":"re.cohort_2025.cpl","second":"re.cohort_2026.cpl"},"label":"cohort CPL"},{"$pair":{"first":"re.cohort_2025.leads","second":"re.cohort_2026.leads"},"label":"recorded leads"},{"value":"{{metric:re.form_submissions}}","label":"Meta form submissions","evidence":"{{evidence:re.form_submissions}}"}],"cta":{"heading":"Running Meta lead campaigns?","body":"Let us look at your numbers."}},"campaignsHeading":"{{metric:re.top5.campaign_count|words_capitalised}} campaigns that carried the volume","sections":[{"id":"context","navLabel":"Context","heading":"Context"},{"id":"methodology","navLabel":"How to read this","heading":"How to read this comparison"},{"id":"cohorts","navLabel":"Cohort comparison","heading":"The cohort comparison"},{"id":"result-types","navLabel":"Result types","heading":"What Meta was actually optimising for"},{"id":"campaigns","navLabel":"Campaign evidence","heading":"{{metric:re.top5.campaign_count|words_capitalised}} campaigns that carried the volume"},{"id":"variants","navLabel":"Variant observations","heading":"Variant observations"},{"id":"blended","navLabel":"Conservative blend","heading":"The conservative blended number"},{"id":"scale","navLabel":"Operational scale","heading":"Operational scale"},{"id":"limitations","navLabel":"Limitations","heading":"What this evidence does not establish"},{"id":"takeaway","navLabel":"Takeaway","heading":"Takeaway"}],"heroMetrics":[{"value":"{{metric:re.cohort_2025.cpl}}","label":"2025 cohort CPL","evidence":"{{evidence:re.cohort_2025.cpl}}"},{"value":"{{metric:re.cohort_2026.cpl}}","label":"2026 cohort CPL","evidence":"{{evidence:re.cohort_2026.cpl}}"},{"$pair":{"first":"re.cohort_2025.leads","second":"re.cohort_2026.leads"},"label":"recorded leads"},{"value":"{{metric:re.cohort.cpl_change_pct}}","label":"reported CPL reduction","evidence":"{{evidence:re.cohort.cpl_change_pct}}"}],"context":[{"term":"Industry","value":"Real Estate"},{"term":"Platform","value":"Meta Ads"},{"term":"Market","value":"Patna + surrounding Bihar cities"},{"term":"Campaign focus","value":"Residential real estate lead generation"}],"methodology":{"body":["The cohorts below are grouped by campaign start year and include only campaigns that recorded results.","This is an observed comparison, not a controlled before/after experiment. Spend levels, projects, creative and platform delivery all changed between the two cohorts, so the difference in cost per lead cannot be attributed to any single decision."],"labelPrimary":"Observed campaign cohorts","labelSecondary":"Not a controlled experiment"},"cohorts":[{"name":"2025 cohort","spend":"{{metric:re.cohort_2025.spend}}","leads":"{{metric:re.cohort_2025.leads}}","cpl":"{{metric:re.cohort_2025.cpl}}","cplValue":{"$metricValue":"re.cohort_2025.cpl"},"leadsValue":{"$metricValue":"re.cohort_2025.leads"}},{"name":"2026 cohort","spend":"{{metric:re.cohort_2026.spend}}","leads":"{{metric:re.cohort_2026.leads}}","cpl":"{{metric:re.cohort_2026.cpl}}","cplValue":{"$metricValue":"re.cohort_2026.cpl"},"leadsValue":{"$metricValue":"re.cohort_2026.leads"}}],"cohortObservations":["Spend increased approximately {{metric:re.cohort.spend_multiple}}.","Lead volume increased approximately {{metric:re.cohort.lead_multiple}}.","Reported CPL fell {{metric:re.cohort.cpl_change_pct}} across the observed cohorts."],"resultTypesTable":{"caption":"Meta result types and reported cost per result","columns":[{"key":"type","header":"Result type"},{"key":"cost","header":"Cost per result","numeric":true}],"rows":[{"type":"Messaging conversations","cost":"{{metric:re.result_type.messaging.cost_per_result}}"},{"type":"Standard lead generation","cost":"{{metric:re.result_type.standard_lead.cost_per_result}}"},{"type":"Meta quality-lead optimisation","cost":"{{metric:re.result_type.quality_lead.cost_per_result}}"},{"type":"Native calls","cost":"{{metric:re.result_type.native_call.cost_per_result}}"}],"note":"Meta quality-lead optimisation is a platform optimisation setting with its own reported cost per result. The {{metric:re.result_type.quality_lead.cost_per_result}} figure is not a measure of independently verified, human-qualified leads and is not described as one anywhere on this site."},"resultTypesChipNote":"The {{metric:re.result_type.quality_lead.cost_per_result}} figure is Meta’s cost per quality-optimised result, not a verified human-qualified lead cost.","resultTypesCommentary":["These four result types are not interchangeable. A messaging conversation, a lead form submission, a quality-optimised lead and a native call are different events with different downstream value, so comparing their cost per result only means something once you have decided which event actually matters to the business.","That decision is a business question rather than a platform question — and it is the one worth settling before any of these numbers is used to move budget."],"campaignsIntro":"{{metric:re.top5.campaign_count|words_capitalised}} campaigns account for {{metric:re.top5.leads}} of the recorded leads. The spread between the cheapest and the most expensive is close to {{metric:re.top5.cpl_spread}}, which is the more useful number: it says the difference sits in the campaign, not in the platform.","campaignsTable":{"caption":"{{metric:re.top5.campaign_count|words_capitalised}} campaigns by recorded leads and cost per lead","columns":[{"key":"campaign","header":"Campaign"},{"key":"leads","header":"Recorded leads","numeric":true},{"key":"cpl","header":"CPL","numeric":true}],"rows":[{"campaign":"{{label:SCE Gayatri|Project A}}","leads":"{{metric:re.project_a.leads}}","cpl":"{{metric:re.project_a.cpl}}"},{"campaign":"{{label:Nutan Construction Project 4|Project B}}","leads":"{{metric:re.project_b.leads}}","cpl":"{{metric:re.project_b.cpl}}"},{"campaign":"{{label:South City Centre 2|Project C}}","leads":"{{metric:re.project_c.leads}}","cpl":"{{metric:re.project_c.cpl}}"},{"campaign":"{{label:Balaji Leads|Project D}}","leads":"{{metric:re.project_d.leads}}","cpl":"{{metric:re.project_d.cpl}}"},{"campaign":"{{label:Garden Leads|Project E}}","leads":"{{metric:re.project_e.leads}}","cpl":"{{metric:re.project_e.cpl}}"}],"footRow":{"campaign":"Combined — {{metric:re.top5.spend}} spend","leads":"{{metric:re.top5.leads}}","cpl":"{{metric:re.top5.cpl}} blended"},"note":"Blended CPL is combined spend divided by combined recorded leads across these {{metric:re.top5.campaign_count|words}} campaigns only. It is not the account-level figure."},"variantsIntro":"{{metric:re.variant.campaign_count|words_capitalised}} campaigns ran alongside a variant. The exports record what each one spent and produced; they do not record why the variant was created.","variantObservations":[{"campaign":"{{label:Aqua City|Project F}}","original":{"spend":"{{metric:re.variant.project_f.original.spend}}","leads":"{{metric:re.variant.project_f.original.leads}} leads","cpl":"{{metric:re.variant.project_f.original.cpl||suffix= CPL}}"},"variant":{"spend":"{{metric:re.variant.project_f.variant.spend}}","leads":"{{metric:re.variant.project_f.variant.leads}} leads","cpl":"{{metric:re.variant.project_f.variant.cpl||suffix= CPL}}"}},{"campaign":"{{label:Urmila|Project G}}","original":{"spend":"{{metric:re.variant.project_g.original.spend}}","leads":"{{metric:re.variant.project_g.original.leads}} leads","cpl":"{{metric:re.variant.project_g.original.cpl||suffix= CPL}}"},"variant":{"spend":"{{metric:re.variant.project_g.variant.spend}}","leads":"{{metric:re.variant.project_g.variant.leads}} leads","cpl":"{{metric:re.variant.project_g.variant.cpl||suffix= CPL}}"}},{"campaign":"{{label:South City Centre|Project C}}","original":{"spend":"{{metric:re.variant.project_c.original.spend}}","leads":"{{metric:re.variant.project_c.original.leads}} leads","cpl":"{{metric:re.variant.project_c.original.cpl||suffix= CPL}}"},"variant":{"spend":"{{metric:re.variant.project_c.variant.spend}}","leads":"{{metric:re.variant.project_c.variant.leads}} results","cpl":"{{metric:re.variant.project_c.variant.cpl||suffix= CPL}}"}}],"variantNote":"The exports show performance differences between campaign variants, but they do not establish the original decision rationale. Nothing here should be read as a claim that a particular creative or copy change caused a particular outcome.","blendedMetrics":[{"value":"{{metric:re.form_submissions}}","label":"Meta form submissions","evidence":"{{evidence:re.form_submissions}}"},{"value":"{{metric:re.blended_cpl}}","label":"conservative blended CPL","evidence":"{{evidence:re.blended_cpl}}"}],"blendedMethodology":["{{metric:re.blended_cpl}} divides all lead-objective spend by Meta form submissions, and it includes {{metric:re.zero_result_lead_spend}} of lead campaigns that recorded no results.","A more flattering figure is available by excluding that spend. It is not used here. Spend that produced no recorded result is still spend, and a cost-per-lead number that quietly removes it is not a number worth planning a budget against."],"operationalScale":[{"value":"{{metric:re.structure.campaigns}}","label":"campaigns"},{"value":"{{metric:re.structure.ad_sets}}","label":"ad sets"},{"value":"{{metric:re.structure.ads}}","label":"ads / creatives"},{"value":"{{metric:re.structure.cities}}","label":"Bihar cities"},{"value":"{{metric:re.structure.objectives}}","label":"campaign objectives"}],"scaleNote":"The exports record that Hindi and English creative variants existed. They do not record a language attribute for every creative, so {{metric:re.structure.ads}} is a count of ads, not a count of bilingual creative pairs.","limitationsIntro":"The available evidence covers platform-recorded activity. It does not confirm any of the following:","limitations":["Qualified lead rate","Site visits","Bookings","Sales","Revenue","Lead-to-sale rate","True cost per acquisition","Offline attribution"],"takeaway":{"heading":"Scaling lead volume is only half the job.","body":["The cohort data shows what a paid social account can do once structure, targeting and creative volume are working: more spend absorbed, considerably more recorded leads, a materially lower reported cost per lead.","It also shows the ceiling of platform-only measurement. Every figure on this page stops at the form submission. The next layer — and the more valuable one — is connecting ad-platform results with lead quality and downstream business outcomes, so that cheaper leads can be tested against better leads rather than assumed to mean the same thing."]}}$ref$::jsonb, 1),
  ('case_study', 'measurement-audit', 'draft', 1, $ref${"summary":{"slug":"measurement-audit","title":"I Audited My Own Ad Accounts Before Optimising Them","cardTitle":"Auditing My Own Ad Accounts","subtitle":"{{metric:audit.unreliable_share|percent_0dp}} of the spend was reporting numbers I could not trust.","cardDescription":"A review of {{metric:site.accounts|words}} ad accounts across Meta and Google, carried out before treating any performance number as a basis for optimisation.","metaDescription":"A measurement audit of {{metric:site.accounts|words}} Meta and Google ad accounts: inflated conversion reporting, placeholder values, unverified conversion actions and incomplete tracking, with the limitations stated.","industry":"Multi-account","platform":"Meta + Google Ads","order":2,"cardMetrics":[{"value":"{{metric:site.spend_total}}","label":"documented spend reviewed","evidence":"{{evidence:site.spend_total}}"},{"value":"{{metric:audit.unreliable_spend|inr_thousands_1dp}}","label":"tied to unreliable measurement","evidence":"{{evidence:audit.unreliable_spend}}"},{"value":"{{metric:audit.unreliable_share}}","label":"of documented spend","evidence":"{{evidence:audit.unreliable_share}}"}],"cta":{"heading":"Not sure whether your conversion data is trustworthy?","body":"That is exactly what a free ad audit is for."}},"sections":[{"id":"situation","navLabel":"Situation","heading":"The situation"},{"id":"checks","navLabel":"What I checked","heading":"What I checked"},{"id":"scale","navLabel":"Scale of the issue","heading":"The scale of the issue"},{"id":"failure-modes","navLabel":"Four failure modes","heading":"Four failure modes"},{"id":"campaign-types","navLabel":"Two campaign types","heading":"Two campaign types, two measurement states"},{"id":"lesson","navLabel":"Central lesson","heading":"The central lesson"},{"id":"limitations","navLabel":"Limitations","heading":"What this review does not establish"}],"heroMetrics":[{"value":"{{metric:site.spend_total}}","label":"documented spend","evidence":"{{evidence:site.spend_total}}"},{"value":"{{metric:site.accounts}}","label":"accounts","evidence":"{{evidence:site.accounts}}"},{"value":"{{metric:audit.unreliable_spend|inr_thousands_1dp}}","label":"associated with unreliable, unverified or inflated measurement","evidence":"{{evidence:audit.unreliable_spend}}"},{"value":"{{metric:audit.unreliable_share}}","label":"of documented spend","evidence":"{{evidence:audit.unreliable_share}}"}],"situation":["{{metric:site.accounts|words_capitalised}} ad accounts across Meta and Google were reviewed before treating performance numbers as optimisation truth.","The order matters. Optimising against a conversion column you have not checked is not optimisation — it is guessing with extra steps. So before any budget decision, the question was narrower and duller: do these numbers describe something real, and do they describe the same thing consistently?","For roughly a third of the documented spend, the answer was no."],"situationNote":"The exact technical cause of every issue was not established from the exports alone, and none is asserted here.","auditChecks":[{"title":"Conversion recording","description":"Whether the account records conversions at all, and in which column."},{"title":"Conversion plausibility vs clicks","description":"Whether reported conversion counts and rates are arithmetically possible given recorded click volume."},{"title":"Conversion diagnostics","description":"The platform’s own status flags on each conversion action."},{"title":"Placeholder values","description":"Conversion values that are defaults or stand-ins rather than real business values."},{"title":"Agreement between reports","description":"Whether campaign-level and account-level figures reconcile with each other."},{"title":"Measurement parity across campaign types","description":"Whether different campaign types in the same account are measured on comparable terms."},{"title":"Conversion-action status","description":"Whether each conversion action is verified, active and currently recording."},{"title":"Platform events vs business outcomes","description":"Whether a recorded platform event can be tied to a defined business outcome at all."}],"scaleFlow":[{"label":"Documented spend reviewed","value":"{{metric:site.spend_total|inr_whole|+}}","tone":"neutral"},{"label":"Spend where measurement did not hold up","value":"{{metric:audit.unreliable_spend}}","tone":"flag"},{"label":"Share of documented spend","value":"{{metric:audit.unreliable_share}}","tone":"flag"}],"failureModes":[{"number":"01","title":"Inflated conversion reporting","summary":"Reported conversion rates that cannot be reconciled with recorded click volume.","body":["One Google account reported campaign-level conversion rates far above 100%, alongside an account-level figure of {{metric:audit.acct_inflated.conv_rate}}.","A conversion rate above 100% is not automatically an error — duplicate counting, multi-conversion actions and attribution settings can all produce one legitimately. What it is, always, is a signal to stop and check before the number is used to justify a budget change."],"metrics":[{"value":"{{metric:audit.acct_inflated.spend}}","label":"spend in the affected account","evidence":"{{evidence:audit.acct_inflated.spend}}"},{"value":"{{metric:audit.acct_inflated.conv_rate}}","label":"account-level reported conversion rate","evidence":"{{evidence:audit.acct_inflated.conv_rate}}"}],"table":{"caption":"Campaign-level reported conversion rates in the affected account","columns":[{"key":"campaign","header":"Campaign"},{"key":"rate","header":"Reported conversion rate","numeric":true}],"rows":[{"campaign":"Campaign 1","rate":"{{metric:audit.acct_inflated.campaign_1.conv_rate}}"},{"campaign":"Campaign 2","rate":"{{metric:audit.acct_inflated.campaign_2.conv_rate}}"},{"campaign":"Campaign 3","rate":"{{metric:audit.acct_inflated.campaign_3.conv_rate}}"},{"campaign":"Campaign 4","rate":"{{metric:audit.acct_inflated.campaign_4.conv_rate}}"}],"footRow":{"campaign":"Account level","rate":"{{metric:audit.acct_inflated.conv_rate}}"},"note":"Campaigns are numbered rather than named here because the point is the pattern across the account, not any individual campaign."},"caution":"The exports show mathematically implausible conversion reporting; the precise technical cause was not established from the exports alone."},{"number":"02","title":"Placeholder values","summary":"Conversion values recorded as {{metric:audit.placeholder_conversion_value}} rather than a real business value.","body":["{{metric:audit.placeholder_value_campaigns|words_capitalised}} campaigns contained {{metric:audit.placeholder_conversion_value}} conversion values.","A {{metric:audit.placeholder_conversion_value}} value is a placeholder, not a price. Any downstream figure built on it — conversion value, value per conversion, ROAS — inherits the placeholder and reports it as though it were revenue."],"metrics":[{"value":"{{metric:audit.placeholder_value_campaigns}}","label":"campaigns with {{metric:audit.placeholder_conversion_value}} conversion values","evidence":"{{evidence:audit.placeholder_value_campaigns}}"}],"caution":"Value-based reporting was therefore not meaningful for those campaigns, and no value-based metric from them appears anywhere on this site."},{"number":"03","title":"Unverified or inactive conversion actions","summary":"Conversion actions present in the account but not verified and not currently recording.","body":["In one preschool account, the platform’s own diagnostics flagged a set of conversion actions as unverified or dormant, while campaigns in that account continued to spend.","The Performance Max campaign in the same account is the clearest illustration: substantial click volume at a low cost per click, a lead-funnel figure reported in one place, and nothing at all in the conversions column."],"metrics":[{"value":"{{metric:pre.account_a.spend}}","label":"spend in the affected account","evidence":"{{evidence:pre.account_a.spend}}"},{"value":"{{metric:pre.account_a.conversion_actions.unverified}}","label":"conversion actions unverified","evidence":"{{evidence:pre.account_a.conversion_actions.unverified}}"},{"value":"{{metric:pre.account_a.conversion_actions.no_recent_conversions}}","label":"with no recent conversions","evidence":"{{evidence:pre.account_a.conversion_actions.no_recent_conversions}}"},{"value":"{{metric:pre.account_a.conversion_actions.actively_recording}}","label":"actively recording","evidence":"{{evidence:pre.account_a.conversion_actions.actively_recording}}"}],"caution":"A campaign recording 0 conversions in the platform’s conversion column is a statement about measurement, not about whether the campaign produced enquiries. This review does not establish that it produced none."},{"number":"04","title":"Incomplete or zero-result tracking","summary":"Spend running against campaigns with no usable recorded outcome.","body":["Across two further preschool accounts and a set of Meta website lead campaigns, spend accumulated against tracking that was incomplete or recorded no results.","This is the least dramatic failure mode and the most common one. Nothing looks broken on the surface; the account simply cannot answer the question it is being asked."],"metrics":[{"value":"{{metric:audit.incomplete_tracking.spend}}","label":"combined spend","evidence":"{{evidence:audit.incomplete_tracking.spend}}"},{"value":"{{metric:audit.incomplete_tracking.sources}}","label":"sources: two preschool accounts and Meta website lead campaigns","evidence":"{{evidence:audit.incomplete_tracking.sources}}"}],"caution":"This describes the state of the recorded tracking. It does not establish that these campaigns generated no enquiries, and it does not identify the technical cause."}],"failureModesNote":"The three spend figures above — {{metric:audit.acct_inflated.spend}}, {{metric:pre.account_a.spend}} and {{metric:audit.incomplete_tracking.spend}} — sum to the {{metric:audit.unreliable_spend}} quoted at the top of this page.","campaignTypes":[{"name":"Performance Max","rows":[{"term":"Spend","value":"{{metric:pre.account_a.pmax.spend}}","evidence":"{{evidence:pre.account_a.pmax.spend}}"},{"term":"Clicks","value":"{{metric:pre.account_a.pmax.clicks}}","evidence":"{{evidence:pre.account_a.pmax.clicks}}"},{"term":"CPC","value":"{{metric:pre.account_a.pmax.cpc}}","evidence":"{{evidence:pre.account_a.pmax.cpc}}"},{"term":"Recorded conversions","value":"{{metric:pre.account_a.pmax.recorded_conversions}}","evidence":"{{evidence:pre.account_a.pmax.recorded_conversions}}"}]},{"name":"Search","rows":[{"term":"Spend","value":"{{metric:pre.account_a.search.spend}}","evidence":"{{evidence:pre.account_a.search.spend}}"},{"term":"Clicks","value":"{{metric:pre.account_a.search.clicks}}","evidence":"{{evidence:pre.account_a.search.clicks}}"},{"term":"CPC","value":"{{metric:pre.account_a.search.cpc}}","evidence":"{{evidence:pre.account_a.search.cpc}}"},{"term":"Recorded conversions","value":"{{metric:pre.account_a.search.recorded_conversions}}","evidence":"{{evidence:pre.account_a.search.recorded_conversions}}"}]}],"campaignTypesIntro":"Two campaign types in the same account, presented side by side because they were measured on completely different terms — not because one of them won.","campaignTypesCaution":"This is not evidence that Search outperformed PMax. The sample and measurement conditions are not comparable enough to make that conclusion.","lesson":{"heading":"The first optimisation decision was measurement integrity — not scaling.","body":["Every action available in an ads platform — raising budgets, pausing campaigns, shifting spend between channels, changing bid strategy — depends on the conversion column being a reasonable description of reality.","Where it is not, optimisation does not merely fail to help. It actively moves budget towards whichever campaign happens to be miscounting most confidently.","So the first piece of work in these accounts was not a scaling decision. It was establishing which numbers had earned the right to be optimised against."]},"limitationsIntro":"This review was carried out on exported reporting. It does not establish:","limitations":["Revenue","Qualified leads","Sales","Bookings","ROAS","Reliable cost per acquisition","The precise technical cause of any issue","Actual business outcomes","Lead quality"],"limitationsClosing":"This was a review of exported reporting, not a technical tracking audit of the live accounts. A live audit — tag firing, event parameters, conversion action configuration, deduplication — is a separate piece of work and would be needed to establish causes."}$ref$::jsonb, 2),
  ('case_study', 'preschool-google-ads', 'draft', 1, $ref${"summary":{"slug":"preschool-google-ads","title":"When Google Ads Numbers Don’t Tell the Whole Story","cardTitle":"Diagnosing Preschool Google Ads","subtitle":"Diagnosing preschool campaign performance across {{metric:pre.accounts|words}} accounts, where reported activity and verifiable outcomes didn’t line up.","cardDescription":"{{metric:pre.accounts|words_capitalised}} preschool Google Ads accounts, reviewed campaign by campaign to work out which reported numbers could carry an optimisation decision and which could not.","metaDescription":"Google Ads case study across {{metric:pre.accounts|words}} preschool accounts: Performance Max, Smart and Search campaign performance, conversion diagnostics, and why reported activity and recorded conversions did not line up.","industry":"Education / Preschool","platform":"Google Ads","order":3,"cardMetrics":[{"value":"{{metric:pre.total.spend|inr_thousands_2dp}}","label":"documented spend","evidence":"{{evidence:pre.total.spend}}"},{"value":"{{metric:pre.total.recorded_conversions}}","label":"recorded conversions","evidence":"{{evidence:pre.total.recorded_conversions}}"},{"$pair":{"first":"pre.account_a.pmax.reported_funnel_leads","second":"pre.account_a.pmax.recorded_conversions","separator":" vs ","evidence":"reported"},"label":"reported leads vs recorded conversions"}],"cta":{"heading":"Seeing conversions you can’t confidently explain?","body":"That is worth diagnosing before you spend another rupee against them."}},"sections":[{"id":"terminology","navLabel":"Terminology","heading":"One word, defined precisely"},{"id":"account-a","navLabel":"Account A","heading":"Account A — Performance Max at scale, nothing recorded"},{"id":"account-b","navLabel":"Account B","heading":"Account B — spend without recorded outcomes"},{"id":"account-c","navLabel":"Account C","heading":"Account C — the smallest account, the clearest signal"},{"id":"checks","navLabel":"What I checked","heading":"What I checked"},{"id":"diagnosis","navLabel":"Core diagnosis","heading":"Where the chain breaks"},{"id":"limitations","navLabel":"Limitations","heading":"What this diagnosis does not establish"}],"heroScope":"{{metric:pre.accounts}} accounts","heroMetrics":[{"value":"{{metric:pre.total.spend|inr_thousands_2dp}}","label":"documented spend","evidence":"{{evidence:pre.total.spend}}"},{"value":"{{metric:pre.accounts}}","label":"preschool Google Ads accounts","evidence":"{{evidence:pre.accounts}}"},{"value":"{{metric:pre.total.recorded_conversions}}","label":"recorded conversions","evidence":"{{evidence:pre.total.recorded_conversions}}"},{"$pair":{"first":"pre.account_a.pmax.reported_funnel_leads","second":"pre.account_a.pmax.recorded_conversions","separator":" vs ","evidence":"reported"},"label":"reported lead-funnel leads vs recorded conversions in one campaign"}],"intro":["{{metric:pre.accounts|words_capitalised}} preschool accounts, {{metric:pre.accounts|words}} different campaign-type mixes, and one recurring problem: the numbers describing activity and the numbers describing outcomes were not talking to each other.","This page walks each account in turn. It is a diagnosis of what the reporting can and cannot support — not a claim about which campaigns produced admissions."],"terminology":{"term":"Verified conversion","definition":"A conversion recorded in the platform’s own conversions column.","excludes":["An independently verified business outcome","A confirmed admission","A confirmed enquiry","A confirmed qualified lead"],"note":"Every use of “recorded” or “verified conversion” on this page carries the narrow meaning above and nothing more."},"accounts":[{"id":"account-a","letter":"A","name":"{{label:Pinwheel|Preschool account A}}","metrics":[{"value":"{{metric:pre.account_a.spend}}","label":"documented spend","evidence":"{{evidence:pre.account_a.spend}}"},{"value":"{{metric:pre.account_a.recorded_conversions}}","label":"recorded conversions","evidence":"{{evidence:pre.account_a.recorded_conversions}}"}],"intro":["The largest of the {{metric:pre.accounts|words}} accounts, and the one where the gap between reported activity and recorded outcomes is widest.","The Performance Max campaign absorbed the majority of the spend and produced a large volume of clicks at around a rupee each. In one report it shows {{metric:pre.account_a.pmax.reported_funnel_leads}} lead-funnel leads. In the conversions column it shows nothing."],"campaigns":[{"campaign":"Performance Max","spend":"{{metric:pre.account_a.pmax.spend}}","clicks":"{{metric:pre.account_a.pmax.clicks}}","cpc":"{{metric:pre.account_a.pmax.cpc}}","conversions":"{{metric:pre.account_a.pmax.recorded_conversions}}","flag":"{{metric:pre.account_a.pmax.reported_funnel_leads}} reported lead-funnel leads"},{"campaign":"Search","spend":"{{metric:pre.account_a.search.spend}}","clicks":"{{metric:pre.account_a.search.clicks}}","cpc":"{{metric:pre.account_a.search.cpc}}","conversions":"{{metric:pre.account_a.search.recorded_conversions}}"}],"diagnostics":[{"value":"{{metric:pre.account_a.conversion_actions.unverified}}","label":"conversion actions unverified","evidence":"{{evidence:pre.account_a.conversion_actions.unverified}}"},{"value":"{{metric:pre.account_a.conversion_actions.no_recent_conversions}}","label":"with no recent conversions","evidence":"{{evidence:pre.account_a.conversion_actions.no_recent_conversions}}"}],"note":"The two campaigns above are the ones relevant to this diagnosis; together they do not account for the full {{metric:pre.account_a.spend}} of account spend.","caution":"The Search campaign recorded {{metric:pre.account_a.search.clicks}} clicks. That sample is far too small, and the account’s measurement far too unreliable, to support any conclusion about Search performing better than Performance Max here."},{"id":"account-b","letter":"B","name":"{{label:Birla Open Minds|Preschool account B}}","metrics":[{"value":"{{metric:pre.account_b.spend}}","label":"documented spend","evidence":"{{evidence:pre.account_b.spend}}"},{"value":"{{metric:pre.account_b.recorded_conversions}}","label":"recorded conversions","evidence":"{{evidence:pre.account_b.recorded_conversions}}"}],"intro":["Nearly two thousand recorded clicks across two campaign types, and a single recorded conversion between them.","A Smart campaign spent {{metric:pre.account_b.smart.spend}} for {{metric:pre.account_b.smart.clicks}} clicks and recorded nothing. The Search campaign spent nearly four times as much for fewer clicks and recorded one conversion."],"campaigns":[{"campaign":"Smart","spend":"{{metric:pre.account_b.smart.spend}}","clicks":"{{metric:pre.account_b.smart.clicks}}","conversions":"{{metric:pre.account_b.smart.recorded_conversions}}"},{"campaign":"Search","spend":"{{metric:pre.account_b.search.spend}}","clicks":"{{metric:pre.account_b.search.clicks}}","conversions":"{{metric:pre.account_b.search.recorded_conversions}}"}],"caution":"One recorded conversion is not a performance signal. It is a prompt to check whether the conversion action was configured and firing across both campaign types on the same terms."},{"id":"account-c","letter":"C","name":"{{label:Kidzee|Preschool account C}}","metrics":[{"value":"{{metric:pre.account_c.spend}}","label":"documented spend","evidence":"{{evidence:pre.account_c.spend}}"},{"value":"{{metric:pre.account_c.recorded_conversions}}","label":"recorded conversions","evidence":"{{evidence:pre.account_c.recorded_conversions}}"}],"intro":["The smallest budget of the {{metric:pre.accounts|words}}, and the only account where a campaign recorded conversions at a rate that looks internally consistent.","The Smart campaign recorded {{metric:pre.account_c.smart.recorded_conversions}} conversions from {{metric:pre.account_c.smart.clicks}} clicks. A second Search campaign spent slightly more for more clicks and recorded none. The Performance Max campaign could not be assessed at all."],"campaigns":[{"campaign":"Smart","spend":"{{metric:pre.account_c.smart.spend}}","clicks":"{{metric:pre.account_c.smart.clicks}}","conversions":"{{metric:pre.account_c.smart.recorded_conversions}}"},{"campaign":"Search-2","spend":"{{metric:pre.account_c.search_2.spend}}","clicks":"{{metric:pre.account_c.search_2.clicks}}","conversions":"{{metric:pre.account_c.search_2.recorded_conversions}}"},{"campaign":"Performance Max","spend":"{{metric:pre.account_c.pmax.spend}}","clicks":"{{metric:pre.account_c.pmax.clicks}}","conversions":"{{metric:pre.account_c.pmax.recorded_conversions}}","flag":"Conversion tracking setup incomplete"}],"caution":"Two campaign types in one account, spending comparable amounts, recording completely different outcomes. That divergence is a measurement question before it is a performance question."}],"checks":["Conversion recording","Plausibility versus clicks","Platform diagnostics","Report agreement","Campaign-type measurement parity","Ability to tie platform conversions to a defined business event"],"diagnosisIntro":["Every one of these accounts fails at the same place in the same chain. Delivery works. The conversion action exists. What is missing is any dependable link between a recorded event and a business outcome someone at the school would recognise."],"diagnosisChain":[{"label":"Campaign delivered","note":"Clicks and impressions recorded","state":"ok"},{"label":"Conversion action defined","note":"Actions present in the account","state":"ok"},{"label":"Event recorded","note":"Recording inconsistent across campaign types","state":"uncertain"},{"label":"Event verified","note":"Diagnostics show unverified and dormant actions","state":"uncertain"},{"label":"CRM outcome","note":"Not established by the available evidence","state":"unknown"},{"label":"Business outcome","note":"Not established by the available evidence","state":"unknown"}],"diagnosisNote":"The chain holds through delivery and breaks at recording and verification. Everything downstream of that break is unknown rather than negative — the evidence does not show that outcomes failed to happen, only that it cannot show whether they did.","pmaxNote":{"heading":"Same campaign, two measurement states","reported":{"value":"{{metric:pre.account_a.pmax.reported_funnel_leads}}","label":"reported lead-funnel leads"},"recorded":{"value":"{{metric:pre.account_a.pmax.recorded_conversions}}","label":"recorded conversions in the platform’s conversion column"},"caution":"These are two different reports of the same campaign, not a before-and-after. This is not evidence that the campaign produced no enquiries; it is evidence that the account cannot currently tell you whether it did."},"limitationsIntro":"This diagnosis is based on exported reporting. It does not confirm:","limitations":["Admissions","Qualified leads","Actual enquiries","Site visits","Sales","Revenue","ROI","ROAS","True cost per acquisition","Lead quality","Lead-to-admission rate","The technical cause of the tracking problems","Whether PMax or Search produced better business outcomes"],"limitationsClosing":"This is a diagnosis of exported reporting, not a completed technical tracking implementation. Establishing causes would require access to the live accounts, the tag setup and the conversion action configuration."}$ref$::jsonb, 3),
  ('case_study', 'cross-channel-real-estate', 'draft', 1, $ref${"summary":{"slug":"cross-channel-real-estate","title":"Cross-Channel Lead Generation for Real Estate: Meta + Google Ads","cardTitle":"Cross-Channel Meta + Google Ads","subtitle":"{{metric:cc.total.spend}} managed across {{metric:cc.campaigns|words}} campaigns — with {{metric:cc.meta.leads}} verified Meta leads and {{metric:cc.google.clicks}} Google Search clicks.","cardDescription":"Paid acquisition documented across two platforms for one residential real estate client, and what it takes before the two can honestly be compared.","metaDescription":"Cross-channel real estate case study covering Meta Ads and Google Search: spend, leads, clicks, CPC and CTR across {{metric:cc.campaigns|words}} campaigns, plus why a cross-channel cost-per-lead comparison was not made.","industry":"Real Estate","platform":"Meta + Google Ads","order":4,"cardMetrics":[{"value":"{{metric:cc.total.spend}}","label":"managed across {{metric:cc.campaigns|words}} campaigns","evidence":"{{evidence:cc.total.spend}}"},{"value":"{{metric:cc.meta.leads}}","label":"verified Meta leads","evidence":"{{evidence:cc.meta.leads}}"},{"value":"{{metric:cc.google.clicks}}","label":"Google Search clicks","evidence":"{{evidence:cc.google.clicks}}"}],"cta":{"heading":"Running both Meta and Google Ads?","body":"Let us look at your numbers."}},"metaHeading":"Meta — {{metric:cc.meta.campaigns|words}} campaigns, {{metric:cc.meta.leads}} verified leads","googleHeading":"Google — {{metric:cc.google.campaigns|words}} Search campaigns, {{metric:cc.google.clicks}} clicks","sections":[{"id":"context","navLabel":"Context","heading":"Context"},{"id":"meta","navLabel":"Meta","heading":"Meta — {{metric:cc.meta.campaigns|words}} campaigns, {{metric:cc.meta.leads}} verified leads"},{"id":"google","navLabel":"Google","heading":"Google — {{metric:cc.google.campaigns|words}} Search campaigns, {{metric:cc.google.clicks}} clicks"},{"id":"comparison","navLabel":"Side by side","heading":"The two channels side by side"},{"id":"limitation","navLabel":"Measurement limit","heading":"Why there is no cross-channel CPL here"},{"id":"limitations","navLabel":"Limitations","heading":"What this evidence does not establish"},{"id":"takeaway","navLabel":"Takeaway","heading":"Takeaway"}],"heroMetrics":[{"value":"{{metric:cc.total.spend}}","label":"documented spend across {{metric:cc.campaigns|words}} campaigns","evidence":"{{evidence:cc.total.spend}}"},{"value":"{{metric:cc.meta.leads}}","label":"verified Meta leads","evidence":"{{evidence:cc.meta.leads}}"},{"value":"{{metric:cc.google.clicks}}","label":"Google Search clicks","evidence":"{{evidence:cc.google.clicks}}"},{"value":"{{metric:cc.google.ctr}}","label":"blended Google CTR","evidence":"{{evidence:cc.google.ctr}}"}],"context":[{"term":"Client","value":"Patna-based residential real estate"},{"term":"Platforms","value":"Meta Ads + Google Ads"},{"term":"Campaigns","value":"{{metric:cc.campaigns}} ({{metric:cc.meta.campaigns}} Meta, {{metric:cc.google.campaigns}} Google Search)"},{"term":"Documented spend","value":"{{metric:cc.total.spend}}"}],"contextIntro":["A Patna-based residential real estate client, with paid acquisition activity documented across two platforms.","The exports record what each campaign spent and delivered. They do not record a common start and end date for every campaign, so nothing here should be read as a claim that all {{metric:cc.campaigns|words}} campaigns were necessarily running concurrently."],"metaTable":{"caption":"Meta campaigns","columns":[{"key":"campaign","header":"Campaign"},{"key":"spend","header":"Spend","numeric":true},{"key":"leads","header":"Verified leads","numeric":true},{"key":"cpl","header":"Cost per lead","numeric":true}],"rows":[{"campaign":"{{label:Balaji Leads|Meta campaign 1}}","spend":"{{metric:cc.meta_1.spend}}","leads":"{{metric:cc.meta_1.leads}}","cpl":"{{metric:cc.meta_1.cpl}}"},{"campaign":"{{label:Balaji Exotica|Meta campaign 2}}","spend":"{{metric:cc.meta_2.spend}}","leads":"{{metric:cc.meta_2.leads}}","cpl":"{{metric:cc.meta_2.cpl}}"}],"footRow":{"campaign":"Total Meta","spend":"{{metric:cc.meta.spend}}","leads":"{{metric:cc.meta.leads}}","cpl":"—"},"note":"“Verified leads” means lead form submissions recorded by Meta. It does not mean independently qualified leads, and lead quality is not established by this evidence."},"metaCommentary":["The {{metric:cc.meta.campaigns|words}} Meta campaigns produced very different cost per lead — {{metric:cc.meta_1.cpl}} against {{metric:cc.meta_2.cpl}} — on the same platform, for the same client, in the same market.","That spread is the useful part. It says the difference sits in the campaign itself: the project, the offer, the audience or the creative. Those are testable. A blended Meta average across both would have hidden it."],"googleTable":{"caption":"Google Search campaigns","columns":[{"key":"campaign","header":"Campaign"},{"key":"spend","header":"Spend","numeric":true},{"key":"clicks","header":"Clicks","numeric":true}],"rows":[{"campaign":"{{label:Balaji Project Search|Google campaign 1}}","spend":"{{metric:cc.google_1.spend}}","clicks":"{{metric:cc.google_1.clicks}}"},{"campaign":"{{label:Search-5|Google campaign 2}}","spend":"{{metric:cc.google_2.spend}}","clicks":"{{metric:cc.google_2.clicks}}"},{"campaign":"{{label:Search-2|Google campaign 3}}","spend":"{{metric:cc.google_3.spend}}","clicks":"{{metric:cc.google_3.clicks}}"}],"footRow":{"campaign":"Total Google","spend":"{{metric:cc.google.spend}}","clicks":"{{metric:cc.google.clicks}}"},"note":"Clicks are clicks. They are not leads, and they are not treated as leads anywhere on this page."},"googleMetrics":[{"value":"{{metric:cc.google.spend}}","label":"Google spend","evidence":"{{evidence:cc.google.spend}}"},{"value":"{{metric:cc.google.clicks}}","label":"clicks","evidence":"{{evidence:cc.google.clicks}}"},{"value":"{{metric:cc.google.cpc}}","label":"blended CPC","evidence":"{{evidence:cc.google.cpc}}"},{"value":"{{metric:cc.google.impressions}}","label":"impressions","evidence":"{{evidence:cc.google.impressions}}"},{"value":"{{metric:cc.google.ctr}}","label":"blended CTR","evidence":"{{evidence:cc.google.ctr}}"}],"channelPanels":[{"channel":"Meta","spend":"{{metric:cc.meta.spend}}","outcomeValue":"{{metric:cc.meta.leads}}","outcomeLabel":"verified Meta leads","outcomeEvidence":"{{evidence:cc.meta.leads}}","rows":[{"term":"Campaigns","value":"{{metric:cc.meta.campaigns}}"},{"term":"Recorded outcome","value":"Lead form submissions"},{"term":"Cost per recorded lead","value":"{{metric:cc.meta.cpl_min}} – {{metric:cc.meta.cpl_max}}"}]},{"channel":"Google","spend":"{{metric:cc.google.spend}}","outcomeValue":"{{metric:cc.google.clicks}}","outcomeLabel":"Search clicks","outcomeEvidence":"{{evidence:cc.google.clicks}}","rows":[{"term":"Campaigns","value":"{{metric:cc.google.campaigns}}"},{"term":"Recorded outcome","value":"Clicks, impressions, CTR, CPC"},{"term":"Cost per recorded lead","value":"Not calculable"}],"caveat":"Google lead count is not verified from the available evidence."}],"comparisonCaution":"These panels are deliberately not aligned into a single winner-versus-loser comparison. The two channels are being measured against different outcome definitions, and one of those definitions is not reliable in this dataset.","limitationBody":["Google conversion reporting is not reliable in this dataset. The campaign exports show conversion rates that cannot be reconciled with recorded click volume — figures such as {{metric:cc.google.reported_conversion_rate_1}}, {{metric:cc.google.reported_conversion_rate_2}} and {{metric:cc.google.reported_conversion_rate_3}}.","That rules out a Google cost per lead. It also rules out the comparison a client most often asks for: which channel produced cheaper leads.","The honest answer is that the question cannot be answered from this evidence, and answering it anyway — by dividing Google spend by Google clicks and calling the result a lead cost — would be the single most misleading thing this case study could do."],"inflatedRates":["{{metric:cc.google.reported_conversion_rate_1}}","{{metric:cc.google.reported_conversion_rate_2}}","{{metric:cc.google.reported_conversion_rate_3}}"],"limitationRules":[{"rule":"No Google CPL is calculated.","reason":"The conversion denominator is not trustworthy."},{"rule":"The {{metric:cc.google.clicks}} clicks are never called {{metric:cc.google.clicks}} leads.","reason":"A click is not a lead."},{"rule":"No Meta-versus-Google winner is declared.","reason":"The two channels are not measured on the same outcome."}],"centralInsight":"Cross-channel marketing only becomes comparable when both platforms report the same defined outcome.","limitationsIntro":"The evidence here covers spend and platform-recorded activity across two channels. It does not establish:","limitations":["Google lead count","Google cost per lead","Lead quality on either channel","Which channel produced better business outcomes","Site visits","Bookings","Sales","Revenue","ROAS or ROI","True cost per acquisition"],"limitationsClosing":"The exports also do not record a common start and end date for all {{metric:cc.campaigns|words}} campaigns, so this is a record of documented activity across two platforms rather than a like-for-like comparison of two channels running side by side.","takeaway":{"heading":"The strongest cross-channel lesson is measurement comparability.","comparable":["Spend","Clicks","CTR","CPC","Campaign structure"],"notComparable":["Cost per lead across channels","Lead quality across channels","Which channel produced better business outcomes"],"body":["Spend, clicks, click-through rate, cost per click and campaign structure can all be compared across channels today. They are measured the same way on both platforms.","Meaningful acquisition comparison needs something else: the same trustworthy outcome definition on both sides. Until a lead means the same thing in Meta and in Google — and until both platforms record it dependably — a cross-channel budget decision is being made on a number that only one channel actually has.","That is fixable, and fixing it is usually worth more than any bid adjustment made in the meantime."]}}$ref$::jsonb, 4);

-- 3. One baseline revision per document, identical to its draft --------

insert into public.document_revisions (document_id, content, schema_version, change_summary)
select d.id, d.draft, d.schema_version, 'Baseline import from snapshot/baseline.json'
from public.documents d;

update public.documents d
   set published_revision_id = r.id,
       status = 'published'
  from public.document_revisions r
 where r.document_id = d.id;

